INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM215DV4W', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'Researchers surveyed a random sample of $600$ high school juniors in a state and found that $37\\%$ had visited a college campus. The margin of error is $3.8$ percentage points at a $95\\%$ confidence level. Which conclusion is best supported by the data?', NULL, $lyceon_json$[{"key":"A","text":"It is plausible that between $33.2\\%$ and $40.8\\%$ of all high school juniors in the state have visited a college campus."},{"key":"B","text":"Exactly $37\\%$ of all high school juniors in the state have visited a college campus."},{"key":"C","text":"If another sample of $600$ juniors is taken, exactly $37\\%$ will have visited a college campus."},{"key":"D","text":"At most $40.8\\%$ of juniors nationwide have visited a college campus."}]$lyceon_json$::jsonb, 'A', NULL, E'The confidence interval is $37\\% \\pm 3.8\\%$, giving a range of $33.2\\%$ to $40.8\\%$, which estimates the true population proportion of all juniors in the state. The claim that exactly $37\\%$ of all juniors have visited a campus treats the sample statistic as a parameter, ignoring sampling error. The claim that a new sample will yield exactly $37\\%$ misunderstands that different random samples produce different sample proportions. The claim about juniors nationwide overgeneralizes beyond the population sampled (the state), since the sample was drawn only from that state.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM216BBH2', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'If $\\frac{3(2x - 7)}{4} = \\frac{x + 11}{2}$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{43}{4}$"},{"key":"B","text":"$\\frac{43}{2}$"},{"key":"C","text":"$\\frac{1}{4}$"},{"key":"D","text":"$-\\frac{43}{4}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Multiplying both sides by $4$ gives $3(2x - 7) = 2(x + 11)$. Expanding: $6x - 21 = 2x + 22$. Subtracting $2x$: $4x - 21 = 22$. Adding $21$: $4x = 43$, so $x = \\frac{43}{4}$. The distractor $\\frac{43}{2}$ arises from incorrectly clearing the fractions by multiplying only one side by $4$, effectively leaving a factor of $2$ unaccounted for. The distractor $\\frac{1}{4}$ comes from expanding $3(2x - 7)$ as $6x - 7$ instead of $6x - 21$, leading to $4x = 1$. The distractor $-\\frac{43}{4}$ results from a sign error when collecting terms.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21MO95J', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A car travels $d$ miles using $g$ gallons of fuel. The fuel tank holds $17$ gallons and is currently $\\frac{3}{17}$ full. If the car''s fuel efficiency is $29$ miles per gallon, how many more miles can the car travel before the tank is empty?', NULL, $lyceon_json$[{"key":"A","text":"$87$"},{"key":"B","text":"$406$"},{"key":"C","text":"$493$"},{"key":"D","text":"$29$"}]$lyceon_json$::jsonb, 'A', NULL, E'The tank holds $17$ gallons and is $\\frac{3}{17}$ full, so the remaining fuel is $17 \\times \\frac{3}{17} = 3$ gallons. At $29$ miles per gallon, the car can travel $29 \\times 3 = 87$ miles. The value $406$ comes from computing $29 \\times 14$, treating $\\frac{14}{17}$ of the tank as the remaining fuel rather than $\\frac{3}{17}$. The value $493$ comes from using the full $17$-gallon capacity ($29 \\times 17$), ignoring that the tank is mostly empty. The value $29$ results from reading the fuel efficiency as the answer without multiplying by the gallons remaining.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21YDRBP', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A survey of $200$ employees found that $74$ commute by train, $51$ commute by bus, and $23$ commute by both train and bus. If an employee who commutes by train is selected at random, what is the probability that this employee also commutes by bus?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{23}{200}$"},{"key":"B","text":"$\\frac{23}{102}$"},{"key":"C","text":"$\\frac{23}{74}$"},{"key":"D","text":"$\\frac{23}{51}$"}]$lyceon_json$::jsonb, 'C', NULL, E'This is a conditional probability question. Given the employee commutes by train, the sample space is the $74$ train commuters. Of these, $23$ also commute by bus, so $P(\\text{bus} \\mid \\text{train}) = \\frac{23}{74}$. The distractor $\\frac{23}{200}$ divides by the total number of employees instead of conditioning on train commuters, confusing joint and conditional probability. The distractor $\\frac{23}{102}$ uses an incorrect denominator of $74 + 51 - 23 = 102$, applying inclusion-exclusion when the question asks for conditional probability. The distractor $\\frac{23}{51}$ conditions on bus commuters instead of train commuters, reversing the given condition.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM220IENP', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A recipe calls for $\\frac{5}{3}$ cups of rice for every $7$ servings. How many cups of rice are needed for $39$ servings?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{65}{3}$"},{"key":"B","text":"$\\frac{195}{7}$"},{"key":"C","text":"$\\frac{55}{3}$"},{"key":"D","text":"$\\frac{65}{7}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The ratio is $\\frac{5/3}{7} = \\frac{5}{21}$ cups per serving. For $39$ servings: $\\frac{5}{21} \\times 39 = \\frac{195}{21} = \\frac{65}{3}$ cups. The value $\\frac{195}{7}$ results from multiplying $\\frac{5}{3} \\times 39$ without dividing by $7$, omitting the proportional step. The value $\\frac{55}{3}$ comes from an arithmetic error in the multiplication. The value $\\frac{65}{7}$ results from placing $7$ in the denominator instead of $3$ after simplification.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22E0MFD', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $g$ is defined by $g(x) = 3(x - 5)^2 - 17$. The function $g$ achieves its minimum value at $x = a$. What is the value of $g(a + 2)$?', NULL, $lyceon_json$[{"key":"A","text":"$-17$"},{"key":"B","text":"$-11$"},{"key":"C","text":"$-5$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'C', NULL, E'The function $g(x) = 3(x - 5)^2 - 17$ is in vertex form, so the minimum occurs at $x = a = 5$. Then $a + 2 = 7$, and $g(7) = 3(7 - 5)^2 - 17 = 3(4) - 17 = 12 - 17 = -5$. The distractor $-17$ is the minimum value of $g$ (that is, $g(a) = -17$), which results from stopping at the minimum value without computing $g(a + 2)$. The distractor $-11$ comes from computing $3(2) - 17 = -11$, forgetting to square the quantity $(7 - 5)$ before multiplying by $3$. The distractor $7$ gives the input value $a + 2 = 7$ rather than the output $g(a + 2)$, confusing the argument with the function value.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22QILJH', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'What is the value of \\(y\\) in the solution to the system of equations below?\\n\\n\\(5x - 2y = 19\\)\\n\\(3x + 4y = 53\\)', NULL, $lyceon_json$[{"key":"A","text":"3"},{"key":"B","text":"7"},{"key":"C","text":"8"},{"key":"D","text":"11"}]$lyceon_json$::jsonb, 'C', NULL, E'Multiply the first equation by 2 to get \\(10x - 4y = 38\\). Adding this to the second equation \\(3x + 4y = 53\\) gives \\(13x = 91\\), so \\(x = 7\\). Substituting back: \\(5(7) - 2y = 19\\) gives \\(35 - 2y = 19\\), so \\(2y = 16\\) and \\(y = 8\\). The value 7 is the \\(x\\)-value, not the \\(y\\)-value, reflecting a misread of the question. The value 11 results from an arithmetic slip such as computing \\(2y = 22\\) by subtracting incorrectly. The value 3 comes from an equation setup error such as failing to multiply both sides when scaling for elimination.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23S2NP6', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'A ramp rises at an angle of $23^\\circ$ with the horizontal ground. If the ramp covers a horizontal distance of $14$ feet, which expression gives the vertical rise of the ramp, in feet?', NULL, $lyceon_json$[{"key":"A","text":"$14 \\sin(23^\\circ)$"},{"key":"B","text":"$14 \\cos(23^\\circ)$"},{"key":"C","text":"$14 \\tan(23^\\circ)$"},{"key":"D","text":"$\\frac{14}{\\tan(23^\\circ)}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The vertical rise is the side opposite the $23^\\circ$ angle, and the horizontal distance is the side adjacent to it. The tangent ratio gives $\\tan(23^\\circ) = \\frac{\\text{opposite}}{\\text{adjacent}} = \\frac{\\text{rise}}{14}$, so the rise is $14\\tan(23^\\circ)$. The expression $14\\sin(23^\\circ)$ would be correct only if $14$ were the hypotenuse (the ramp length), not the horizontal distance. The expression $14\\cos(23^\\circ)$ confuses opposite and adjacent sides. The expression $\\frac{14}{\\tan(23^\\circ)}$ inverts the tangent relationship, which would give the adjacent side if $14$ were the opposite side.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24GQ4MJ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A class has $29$ students. Of these, $13$ play basketball, $9$ play soccer, and $4$ play both basketball and soccer. If a student is chosen at random, what is the probability that the student plays basketball or soccer?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{22}{29}$"},{"key":"B","text":"$\\frac{18}{29}$"},{"key":"C","text":"$\\frac{26}{29}$"},{"key":"D","text":"$\\frac{13}{29}$"}]$lyceon_json$::jsonb, 'B', NULL, E'By the inclusion-exclusion principle, $P(\\text{basketball or soccer}) = \\frac{13 + 9 - 4}{29} = \\frac{18}{29}$. The distractor $\\frac{22}{29}$ adds $13 + 9 = 22$ without subtracting the $4$ students counted twice, an equation setup error. The distractor $\\frac{26}{29}$ adds $13 + 9 + 4 = 26$, incorrectly adding the overlap instead of subtracting it. The distractor $\\frac{13}{29}$ considers only basketball players and ignores the soccer-only students entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25FICTU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A health researcher finds that people who walk more than $10{,}000$ steps per day report lower stress levels than people who walk fewer than $3{,}000$ steps per day. This was determined by surveying a group of adults about their walking habits and stress levels. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Walking more than $10{,}000$ steps per day causes lower stress levels."},{"key":"B","text":"There is an association between walking more steps and reporting lower stress levels."},{"key":"C","text":"People with low stress have more free time to walk."},{"key":"D","text":"The survey proves that exercise reduces stress in all adults."}]$lyceon_json$::jsonb, 'B', NULL, E'Because this is an observational study (a survey with no random assignment of walking behavior), no causal conclusion can be drawn. The data support an association between walking more and reporting lower stress. The claim that walking causes lower stress is unsupported because confounding variables (such as overall fitness, lifestyle, or free time) may explain the relationship. The assertion that people with low stress simply have more time to walk introduces a specific causal claim in the reverse direction that is also unsupported by the study design. The claim that the survey proves exercise reduces stress in all adults both asserts causation and overgeneralizes to a population that may not be represented by the sample.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM266BQYS', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'A line passes through the points $(2, -3)$ and $(8, 15)$. What is the equation of the line in slope-intercept form?', NULL, $lyceon_json$[{"key":"A","text":"$y = 3x - 9$"},{"key":"B","text":"$y = 3x + 9$"},{"key":"C","text":"$y = -3x + 3$"},{"key":"D","text":"$y = \\frac{1}{3}x - \\frac{11}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope is $m = \\frac{15 - (-3)}{8 - 2} = \\frac{18}{6} = 3$. Using point-slope form with $(2, -3)$: $y + 3 = 3(x - 2) = 3x - 6$, so $y = 3x - 9$. The distractor $y = 3x + 9$ has the correct slope but the wrong intercept sign, from an error simplifying $y + 3 = 3x - 6$. The distractor $y = -3x + 3$ negates the slope by reversing only the numerator in the slope calculation. The distractor $y = \\frac{1}{3}x - \\frac{11}{3}$ uses the reciprocal of the slope.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26BRCH7', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which of the following values of \\(x\\) satisfies the inequality \\(7x - 13 > 22\\)?', NULL, $lyceon_json$[{"key":"A","text":"3"},{"key":"B","text":"4"},{"key":"C","text":"5"},{"key":"D","text":"6"}]$lyceon_json$::jsonb, 'D', NULL, E'Solving \\(7x - 13 > 22\\) gives \\(7x > 35\\), so \\(x > 5\\). The value 6 is the only option strictly greater than 5. The value 5 is not a solution because the inequality is strict (greater than, not greater than or equal to), reflecting a boundary error. The value 4 results from an arithmetic mistake such as dividing 22 by 7 instead of 35 by 7. The value 3 reflects a fundamental gap in solving the inequality correctly.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM279ZWFL', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What is the value of $x$ in the equation $9x + 14 = 77$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$\\frac{77}{9}$"},{"key":"C","text":"$\\frac{91}{9}$"},{"key":"D","text":"$-7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Subtracting $14$ from both sides gives $9x = 63$, and dividing by $9$ gives $x = 7$. The distractor $\\frac{77}{9}$ results from dividing $77$ by $9$ without first subtracting $14$, ignoring the constant term. The distractor $\\frac{91}{9}$ results from adding $14$ to $77$ instead of subtracting, yielding $9x = 91$. The distractor $-7$ results from a sign error when dividing.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27IJJ5S', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What are the solutions to $x^2 - 11x + 28 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$x = 4$ and $x = 7$"},{"key":"B","text":"$x = -4$ and $x = -7$"},{"key":"C","text":"$x = 14$ and $x = 2$"},{"key":"D","text":"$x = -4$ and $x = 7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factor the quadratic: we need two numbers that multiply to $28$ and add to $-11$. Those numbers are $-4$ and $-7$, so $x^2 - 11x + 28 = (x - 4)(x - 7) = 0$, giving $x = 4$ and $x = 7$. The distractor $x = -4$ and $x = -7$ results from a sign error, incorrectly interpreting the factors as $(x + 4)(x + 7)$. The distractor $x = 14$ and $x = 2$ uses a pair that multiplies to $28$ but sums to $16$, not $11$, an arithmetic mistake in identifying the factor pair. The distractor $x = -4$ and $x = 7$ results from getting one sign correct and the other wrong.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27UQHZD', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'Given the system of equations\\n\\n\\(2x + 7y = 31\\)\\n\\(5x - 3y = -4\\),\\n\\nwhat is the value of \\(7x + 4y\\)?', NULL, $lyceon_json$[{"key":"A","text":"17"},{"key":"B","text":"27"},{"key":"C","text":"35"},{"key":"D","text":"48"}]$lyceon_json$::jsonb, 'B', NULL, E'Adding the two equations directly: \\((2x + 5x) + (7y - 3y) = 31 + (-4)\\), which gives \\(7x + 4y = 27\\). This is exactly the expression the question asks for, so no further work is needed. The value 35 results from a sign error, treating \\(-4\\) as \\(+4\\) when adding the right-hand sides. The value 17 comes from partial reasoning, such as only considering one equation or subtracting instead of adding. The value 48 arises from an arithmetic slip, for example incorrectly adding the coefficients or the constants.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28PY647', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'Two polling organizations each surveyed a random sample of likely voters in the same city about support for a transit measure. Organization X surveyed $900$ voters and found $48\\%$ support with a margin of error of $3.3$ percentage points. Organization Y surveyed $350$ voters and found $54\\%$ support with a margin of error of $5.2$ percentage points. Which statement is best supported by these results?', NULL, $lyceon_json$[{"key":"A","text":"The confidence intervals of the two surveys overlap, so the results are consistent and the true level of support could be within both intervals."},{"key":"B","text":"Organization Y's result is more accurate because its sample proportion is higher."},{"key":"C","text":"Organization X's result must be wrong because it differs from Organization Y's result by $6$ percentage points."},{"key":"D","text":"Neither survey is reliable because the two results are different."}]$lyceon_json$::jsonb, 'A', NULL, E'Organization X''s interval is $44.7\\%$ to $51.3\\%$, and Organization Y''s interval is $48.8\\%$ to $59.2\\%$. These intervals overlap (both include values near $49\\%$–$51\\%$), meaning the results are consistent and the true proportion could fall in both ranges. The claim that Organization Y is more accurate because its proportion is higher confuses a larger estimate with greater accuracy; Organization X actually has a smaller margin of error due to its larger sample. The claim that Organization X must be wrong because the results differ by $6$ points ignores that sampling variability naturally produces different point estimates. The assertion that neither survey is reliable because they differ reflects a misunderstanding of how random sampling works — differing results do not invalidate either survey.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28UAI26', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'What is the value of \\(x\\) in the solution to the system of equations below?\\n\\n\\(3x + y = 23\\)\\n\\(x - y = 1\\)', NULL, $lyceon_json$[{"key":"A","text":"4"},{"key":"B","text":"5"},{"key":"C","text":"6"},{"key":"D","text":"8"}]$lyceon_json$::jsonb, 'C', NULL, E'Adding the two equations eliminates \\(y\\): \\((3x + y) + (x - y) = 23 + 1\\), giving \\(4x = 24\\), so \\(x = 6\\). The value 5 is the corresponding \\(y\\)-value (since \\(y = 6 - 1 = 5\\)), reflecting a misread of which variable the question asks for. The value 4 comes from an arithmetic slip such as dividing 24 by 6 instead of by 4. The value 8 results from incorrectly setting up the elimination, for instance subtracting the equations instead of adding them and then making a further error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM293PWM1', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A taxi service charges a base fare plus a constant rate per mile. A $6$-mile ride costs $\\$15.00$ and a $14$-mile ride costs $\\$29.00$. What is the base fare?', NULL, $lyceon_json$[{"key":"A","text":"$\\$1.75$"},{"key":"B","text":"$\\$2.50$"},{"key":"C","text":"$\\$4.50$"},{"key":"D","text":"$\\$9.00$"}]$lyceon_json$::jsonb, 'C', NULL, E'The rate per mile is $\\frac{29.00 - 15.00}{14 - 6} = \\frac{14}{8} = 1.75$ dollars per mile. Substituting into the first equation: $15.00 = b + 1.75(6) = b + 10.50$, so $b = 4.50$. The base fare is $\\$4.50$. The distractor $\\$1.75$ is the per-mile rate, not the base fare, reflecting a student who finds the rate but reports it as the answer. The distractor $\\$2.50$ comes from dividing $15.00$ by $6$ to get an average cost per mile and confusing that with the base fare. The distractor $\\$9.00$ results from subtracting the number of miles from the total cost ($15 - 6 = 9$).', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29ASEC6', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'A plumber charges a flat fee of $\\$47$ plus $\\$31$ per hour. An electrician charges a flat fee of $\\$83$ plus $\\$22$ per hour. After how many hours will the plumber''s total charge equal the electrician''s total charge?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$4$"},{"key":"C","text":"$\\frac{36}{53}$"},{"key":"D","text":"$\\frac{130}{9}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Setting the charges equal: $47 + 31h = 83 + 22h$. Subtracting $22h$: $47 + 9h = 83$. Subtracting $47$: $9h = 36$, so $h = 4$. The distractor $3$ results from an arithmetic slip such as computing $83 - 47 = 27$ instead of $36$ and then dividing by $9$. The distractor $\\frac{36}{53}$ comes from incorrectly adding the hourly rates ($31 + 22 = 53$) in the denominator instead of subtracting them. The distractor $\\frac{130}{9}$ results from adding the flat fees ($47 + 83 = 130$) instead of subtracting them.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29TKVXG', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'The system of inequalities \\(2x + 5y \\leq 43\\) and \\(3x - y \\geq 2\\) defines a region in the \\(xy\\)-plane. Which of the following points lies in the solution region?', NULL, $lyceon_json$[{"key":"A","text":"\\((1, 9)\\)"},{"key":"B","text":"\\((4, 7)\\)"},{"key":"C","text":"\\((10, 5)\\)"},{"key":"D","text":"\\((0, -1)\\)"}]$lyceon_json$::jsonb, 'B', NULL, E'Testing \\((4, 7)\\): the first inequality gives \\(2(4) + 5(7) = 43 \\leq 43\\) (true), and the second gives \\(3(4) - 7 = 5 \\geq 2\\) (true), so this point satisfies both. Testing \\((1, 9)\\): \\(2(1) + 5(9) = 47 > 43\\), which violates the first inequality; choosing this point reflects checking only the second inequality. Testing \\((10, 5)\\): \\(2(10) + 5(5) = 45 > 43\\), which also violates the first inequality, reflecting a failure to verify both constraints. Testing \\((0, -1)\\): \\(3(0) - (-1) = 1 < 2\\), which violates the second inequality, a sign-handling error when substituting the negative coordinate.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2B7MEJF', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $4x + 2y = 18$?', NULL, $lyceon_json$[{"key":"A","text":"$(0, 9)$"},{"key":"B","text":"$(0, 18)$"},{"key":"C","text":"$(4.5, 0)$"},{"key":"D","text":"$(0, -9)$"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting $x = 0$ gives $2y = 18$, so $y = 9$ and the $y$-intercept is $(0, 9)$. The distractor $(0, 18)$ results from reading the constant as the intercept without dividing by the coefficient of $y$. The distractor $(4.5, 0)$ gives the $x$-intercept instead of the $y$-intercept, confusing which variable to set to zero. The distractor $(0, -9)$ applies an incorrect sign when solving.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BFFJUC', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'For the polynomial function $p(x) = -2x^5 + 9x^3 - 4x + 7$, which of the following correctly describes the end behavior of $p$?', NULL, $lyceon_json$[{"key":"A","text":"As $x \\to -\\infty$, $p(x) \\to \\infty$, and as $x \\to \\infty$, $p(x) \\to -\\infty$"},{"key":"B","text":"As $x \\to -\\infty$, $p(x) \\to -\\infty$, and as $x \\to \\infty$, $p(x) \\to \\infty$"},{"key":"C","text":"As $x \\to -\\infty$, $p(x) \\to \\infty$, and as $x \\to \\infty$, $p(x) \\to \\infty$"},{"key":"D","text":"As $x \\to -\\infty$, $p(x) \\to -\\infty$, and as $x \\to \\infty$, $p(x) \\to -\\infty$"}]$lyceon_json$::jsonb, 'A', NULL, E'End behavior is determined by the leading term $-2x^5$. The degree is $5$ (odd), so the ends go in opposite directions. The leading coefficient is $-2$ (negative), which reverses the standard odd-degree behavior. As $x \\to -\\infty$, $(-2)(-\\infty)^5 = (-2)(- \\infty) = +\\infty$, and as $x \\to \\infty$, $(-2)(\\infty)^5 = -\\infty$. The distractor stating $p(x) \\to -\\infty$ as $x \\to -\\infty$ and $p(x) \\to \\infty$ as $x \\to \\infty$ ignores the negative leading coefficient, applying the end behavior of a positive odd-degree polynomial. The distractor stating both ends go to $\\infty$ incorrectly treats the polynomial as even-degree with a positive leading coefficient. The distractor stating both ends go to $-\\infty$ incorrectly treats the polynomial as even-degree with a negative leading coefficient.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BJ76PY', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which of the following is equivalent to $\\frac{4x^2 - 36}{2x^2 + 14x + 24}$ for all values of $x$ where the expression is defined?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{2(x - 3)}{x + 4}$"},{"key":"B","text":"$\\frac{2(x + 3)}{x + 4}$"},{"key":"C","text":"$\\frac{2x - 6}{x + 3}$"},{"key":"D","text":"$\\frac{4(x - 3)}{2x + 8}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factor the numerator: $4x^2 - 36 = 4(x^2 - 9) = 4(x-3)(x+3)$. Factor the denominator: $2x^2 + 14x + 24 = 2(x^2 + 7x + 12) = 2(x+3)(x+4)$. Cancel the common factor $(x+3)$: $\\frac{4(x-3)}{2(x+4)} = \\frac{2(x-3)}{x+4}$. The distractor $\\frac{2(x+3)}{x+4}$ results from a sign error when factoring $x^2 - 9$, incorrectly keeping $(x+3)$ in the numerator instead of $(x-3)$ after cancellation. The distractor $\\frac{2x - 6}{x + 3}$ cancels $(x+4)$ instead of the common factor $(x+3)$, an error in identifying which factor is shared. The distractor $\\frac{4(x-3)}{2x+8}$ correctly factors and cancels $(x+3)$ but fails to simplify the ratio $\\frac{4}{2}$, leaving the expression not fully reduced.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BUJZ7X', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, angle $P$ measures $47^\\circ$ and angle $Q$ measures $68^\\circ$. An exterior angle is formed at vertex $R$. What is the measure, in degrees, of this exterior angle?', NULL, $lyceon_json$[{"key":"A","text":"$65$"},{"key":"B","text":"$115$"},{"key":"C","text":"$133$"},{"key":"D","text":"$112$"}]$lyceon_json$::jsonb, 'B', NULL, E'The interior angle at $R$ is $180 - 47 - 68 = 65^\\circ$. The exterior angle at $R$ is supplementary to the interior angle: $180 - 65 = 115^\\circ$. Equivalently, by the exterior angle theorem, the exterior angle equals the sum of the two non-adjacent interior angles: $47 + 68 = 115$. The distractor $65$ is the interior angle at $R$, stopping before computing the exterior angle. The distractor $133$ results from adding $68 + 65$, incorrectly summing the wrong pair. The distractor $112$ comes from a computational error such as $47 + 65$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BY493Y', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'The equation $7x^2 + kx + 7 = 0$, where $k$ is a constant, has exactly one real solution. What is the positive value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$14$"},{"key":"C","text":"$49$"},{"key":"D","text":"$196$"}]$lyceon_json$::jsonb, 'B', NULL, E'A quadratic equation has exactly one real solution when the discriminant equals zero. For $7x^2 + kx + 7 = 0$, the discriminant is $k^2 - 4(7)(7) = k^2 - 196$. Setting $k^2 - 196 = 0$ gives $k^2 = 196$, so $k = \\pm 14$. The positive value is $14$. The distractor $7$ results from using $k^2 = ac = 7 \\cdot 7 = 49$ (omitting the factor of $4$ in the discriminant formula) and then taking $k = 7$. The distractor $49$ results from computing $k = 4ac/4 = ac = 49$, confusing $k^2$ with $k$. The distractor $196$ gives the value of $k^2$ rather than $k$, stopping one step short of the solution.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C9PLF0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'A data set of $11$ values has a mean of $37$ and a median of $41$. Two additional values, $13$ and $17$, are added to the data set. What is the new median of the $13$-value data set if all original values sorted are $21, 25, 29, 33, 37, 41, 41, 41, 43, 47, 49$?', NULL, $lyceon_json$[{"key":"A","text":"$37$"},{"key":"B","text":"$41$"},{"key":"C","text":"$39$"},{"key":"D","text":"$33$"}]$lyceon_json$::jsonb, 'A', NULL, E'Sorting all $11$ original values: $21, 25, 29, 33, 37, 41, 41, 41, 43, 47, 49$. Adding $13$ and $17$ gives $13$ values sorted as $13, 17, 21, 25, 29, 33, 37, 41, 41, 41, 43, 47, 49$. The median is the $7$th value, which is $37$. The value $41$ is the old median, not the new one after inserting two values below the center. The value $39$ results from averaging the old and new medians. The value $33$ comes from miscounting and selecting the $6$th value instead of the $7$th.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CIZHWN', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $25x^2 - 81$?', NULL, $lyceon_json$[{"key":"A","text":"$(5x - 9)^2$"},{"key":"B","text":"$(25x - 9)(x + 9)$"},{"key":"C","text":"$(5x - 9)(5x + 9)$"},{"key":"D","text":"$(5x - 81)(5x + 1)$"}]$lyceon_json$::jsonb, 'C', NULL, E'The expression $25x^2 - 81$ is a difference of two squares: $25x^2 = (5x)^2$ and $81 = 9^2$. Applying the identity $a^2 - b^2 = (a-b)(a+b)$ gives $(5x - 9)(5x + 9)$. The distractor $(5x - 9)^2$ confuses the difference of squares with a perfect square trinomial, since $(5x - 9)^2 = 25x^2 - 90x + 81 \\neq 25x^2 - 81$. The distractor $(25x - 9)(x + 9)$ fails to take the square root of $25x^2$, incorrectly splitting the first term. The distractor $(5x - 81)(5x + 1)$ sets up the factorization incorrectly, producing a product that does not equal the original expression.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DUDPAX', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $400$ voters in a city found that $53\\%$ support a proposed park renovation. The margin of error for the survey is $4$ percentage points. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Between $49\\%$ and $57\\%$ of all voters in the city likely support the renovation."},{"key":"B","text":"Exactly $53\\%$ of all voters in the city support the renovation."},{"key":"C","text":"Between $49\\%$ and $57\\%$ of the sampled voters support the renovation."},{"key":"D","text":"The survey result will change by $4\\%$ if repeated."}]$lyceon_json$::jsonb, 'A', NULL, E'The margin of error creates a confidence interval around the sample proportion: $53\\% \\pm 4\\%$, or $49\\%$ to $57\\%$, estimating the true population proportion. The claim that exactly $53\\%$ of all voters support the renovation ignores sampling variability and the purpose of the margin of error. The statement that $49\\%$ to $57\\%$ of the sampled voters support the renovation misapplies the interval to the sample rather than the population — the sample result is a fixed $53\\%$. The claim that the survey result will change by $4\\%$ if repeated misinterprets margin of error as a measure of result variability across surveys.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ISBBP1', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'A function is defined by $f(x) = -4x + 13$. What is $f(3)$?', NULL, $lyceon_json$[{"key":"A","text":"$25$"},{"key":"B","text":"$1$"},{"key":"C","text":"$-1$"},{"key":"D","text":"$-25$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $x = 3$: $f(3) = -4(3) + 13 = -12 + 13 = 1$. The distractor $25$ comes from ignoring the negative sign and computing $4(3) + 13$. The distractor $-1$ results from computing $-13 + 12$ instead of $-12 + 13$, reversing the addition order and signs. The distractor $-25$ comes from computing $-(4(3) + 13) = -25$, applying the negative to the entire expression.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JBU2VV', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A cone has a slant height of $19$ cm and a base radius of $7$ cm. What is the total surface area of the cone, in square centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$182\\pi$"},{"key":"B","text":"$133\\pi$"},{"key":"C","text":"$266\\pi$"},{"key":"D","text":"$68\\pi$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total surface area of a cone is $\\pi r l + \\pi r^2$, where $r = 7$ and $l = 19$ (slant height). This gives $\\pi(7)(19) + \\pi(7)^2 = 133\\pi + 49\\pi = 182\\pi$ square centimeters. The distractor $133\\pi$ computes only the lateral surface area ($\\pi r l$), omitting the circular base. The distractor $266\\pi$ doubles the lateral area ($2\\pi r l$), incorrectly treating the cone like a cylinder''s lateral surface. The distractor $68\\pi$ adds the base area $49\\pi$ to $19\\pi$ instead of to $\\pi r l = 133\\pi$, confusing the slant height with the lateral surface area formula.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K4OD1N', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot shows a set of data points that cluster closely around a line sloping downward from left to right. Which of the following best describes the association between the two variables?', NULL, $lyceon_json$[{"key":"A","text":"Strong positive linear association"},{"key":"B","text":"Weak positive linear association"},{"key":"C","text":"Strong negative linear association"},{"key":"D","text":"No association"}]$lyceon_json$::jsonb, 'C', NULL, E'Points clustering closely around a downward-sloping line indicate a strong negative linear association. A strong positive linear association would require an upward slope. A weak positive association would show scattered points around an upward line. No association would mean the points show no discernible pattern.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KCKZQ7', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = (x - 7)^2 + 11$. What is the minimum value of $f(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$-11$"},{"key":"B","text":"$7$"},{"key":"C","text":"$11$"},{"key":"D","text":"$60$"}]$lyceon_json$::jsonb, 'C', NULL, E'The function $f(x) = (x - 7)^2 + 11$ is in vertex form $a(x - h)^2 + k$ with $a = 1 > 0$, $h = 7$, and $k = 11$. Since the parabola opens upward, the vertex $(7, 11)$ is the minimum point, and the minimum value of $f(x)$ is $11$. The distractor $-11$ results from negating the constant term, a sign error. The distractor $7$ gives the $x$-coordinate of the vertex rather than the minimum value, answering the wrong part of the question. The distractor $60$ comes from evaluating $f(0) = (0-7)^2 + 11 = 49 + 11 = 60$, incorrectly assuming the minimum occurs at $x = 0$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KECU11', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A factory produces $84$ widgets in $7$ hours. At this constant rate, how many widgets does the factory produce in $11$ hours?', NULL, $lyceon_json$[{"key":"A","text":"$121$"},{"key":"B","text":"$132$"},{"key":"C","text":"$154$"},{"key":"D","text":"$924$"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate is $\\frac{84}{7} = 12$ widgets per hour. In $11$ hours the factory produces $12 \\times 11 = 132$ widgets. The value $121$ results from squaring $11$ instead of multiplying by the rate. The value $154$ comes from incorrectly computing the rate as $14$ per hour. The value $924$ results from multiplying $84 \\times 11$ without first finding the unit rate.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KXF721', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two parallel lines are cut by a transversal. One of the alternate interior angles measures $53^\\circ$. What is the measure, in degrees, of the other alternate interior angle?', NULL, $lyceon_json$[{"key":"A","text":"$53$"},{"key":"B","text":"$127$"},{"key":"C","text":"$37$"},{"key":"D","text":"$106$"}]$lyceon_json$::jsonb, 'A', NULL, E'Alternate interior angles formed by parallel lines and a transversal are congruent, so the other angle also measures $53^\\circ$. The distractor $127$ results from computing the supplement ($180 - 53$) instead of recognizing the congruence property. The distractor $37$ comes from subtracting from $90$ rather than $180$, confusing complementary and supplementary relationships. The distractor $106$ doubles the given angle, which has no geometric basis here.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L8UPWR', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'The graphs of $y = x^2 - 4x + 3$ and $y = 3x - 7$ intersect at two points in the $xy$-plane. What is the $y$-coordinate of the intersection point with the greater $x$-coordinate?', NULL, $lyceon_json$[{"key":"A","text":"$-1$"},{"key":"B","text":"$5$"},{"key":"C","text":"$8$"},{"key":"D","text":"$-8$"}]$lyceon_json$::jsonb, 'C', NULL, E'Set the expressions equal: $x^2 - 4x + 3 = 3x - 7$, which simplifies to $x^2 - 7x + 10 = 0$. Factoring gives $(x - 2)(x - 5) = 0$, so $x = 2$ or $x = 5$. The greater $x$-coordinate is $5$. Substituting into $y = 3x - 7$: $y = 3(5) - 7 = 8$. The distractor $-1$ is the $y$-coordinate of the other intersection point (at $x = 2$, $y = 3(2) - 7 = -1$), answering for the wrong point. The distractor $5$ gives the $x$-coordinate rather than the $y$-coordinate, reflecting incomplete reasoning. The distractor $-8$ applies an incorrect sign to the correct magnitude.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LA869G', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A university researcher randomly assigned $130$ students to two groups. One group studied with instrumental music playing and the other studied in silence. After two weeks, both groups took the same exam. The group that studied with music scored an average of $4.7$ points higher. Which conclusion is best supported by the study design?', NULL, $lyceon_json$[{"key":"A","text":"Studying with instrumental music causes higher exam scores in the general population."},{"key":"B","text":"There is an association between music and exam scores, but causation cannot be established."},{"key":"C","text":"Studying with instrumental music likely caused the higher scores among the students in the study."},{"key":"D","text":"Students who enjoy music tend to score higher on exams."}]$lyceon_json$::jsonb, 'C', NULL, E'Because students were randomly assigned to groups, this is a controlled experiment, which can support a causal conclusion among the participants. The claim that music causes higher scores in the general population overgeneralizes, since the subjects were university students, not a representative sample of everyone. The assertion that only an association can be established fails to recognize that random assignment in an experiment allows for causal inference. The claim about students who enjoy music scoring higher introduces a preference variable not addressed in the study — students were randomly assigned regardless of music preference.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LIIF4E', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A cylinder has a radius of $5$ inches and a height of $11$ inches. What is the total surface area of the cylinder, in square inches?', NULL, $lyceon_json$[{"key":"A","text":"$160\\pi$"},{"key":"B","text":"$110\\pi$"},{"key":"C","text":"$275\\pi$"},{"key":"D","text":"$55\\pi$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total surface area of a cylinder is $2\\pi r^2 + 2\\pi r h = 2\\pi(25) + 2\\pi(5)(11) = 50\\pi + 110\\pi = 160\\pi$ square inches. The distractor $110\\pi$ computes only the lateral surface area ($2\\pi r h = 2\\pi(5)(11)$), omitting the two circular bases. The distractor $275\\pi$ computes the volume ($\\pi r^2 h = \\pi(25)(11) = 275\\pi$) instead of the surface area. The distractor $55\\pi$ computes $\\pi r h = \\pi(5)(11)$, forgetting to multiply the lateral area by $2$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MCJKJD', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'A store marks up a product by $40\\%$ over its wholesale cost and then offers a $25\\%$ discount on the marked-up price. If the final selling price is $\\$63$, what was the wholesale cost?', NULL, $lyceon_json$[{"key":"A","text":"$\\$48$"},{"key":"B","text":"$\\$60$"},{"key":"C","text":"$\\$72$"},{"key":"D","text":"$\\$84$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let the wholesale cost be $w$. The marked-up price is $1.40w$, and after a $25\\%$ discount the selling price is $0.75 \\times 1.40w = 1.05w$. Setting $1.05w = 63$ gives $w = 60$. The value $\\$48$ results from dividing $63$ by $1.40$ and then subtracting $25\\%$, applying the operations in the wrong order on the result. The value $\\$72$ comes from dividing $63$ by $0.75$ alone and treating that as the wholesale cost, ignoring the markup step. The value $\\$84$ comes from dividing $63$ by $0.75$ to get $84$ and stopping there, which gives the marked-up price rather than the wholesale cost.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N6TWQX', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A researcher collects data on the number of hours studied ($x$) and exam score ($y$) for $9$ students. The line of best fit is $y = 4.7x + 51.3$, and one student who studied $6$ hours scored $83$. What is the residual for this student?', NULL, $lyceon_json$[{"key":"A","text":"$3.5$"},{"key":"B","text":"$-3.5$"},{"key":"C","text":"$79.5$"},{"key":"D","text":"$28.2$"}]$lyceon_json$::jsonb, 'A', NULL, E'The predicted score for $x = 6$ is $y = 4.7(6) + 51.3 = 28.2 + 51.3 = 79.5$. The residual is the actual value minus the predicted value: $83 - 79.5 = 3.5$. The value $-3.5$ reverses the subtraction order (predicted minus actual). The value $79.5$ is the predicted score itself, not the residual. The value $28.2$ is only the product $4.7 \\times 6$, failing to add the intercept or compute the residual.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OXSLGD', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangular box has a length of $13$ cm, a width of $7$ cm, and a height of $4$ cm. What is the volume of the box, in cubic centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$364$"},{"key":"B","text":"$91$"},{"key":"C","text":"$24$"},{"key":"D","text":"$342$"}]$lyceon_json$::jsonb, 'A', NULL, E'The volume of a rectangular box is $V = l \\times w \\times h = 13 \\times 7 \\times 4 = 364$ cubic centimeters. The distractor $91$ computes only $13 \\times 7$, using two dimensions instead of three. The distractor $24$ adds the three dimensions ($13 + 7 + 4$) instead of multiplying them. The distractor $342$ results from a multiplication error, such as computing $13 \\times 6 \\times 4$ or misreading one dimension.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PPGJC3', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'From the top of a $73$-meter cliff, an observer looks down at a boat in the sea. The angle of depression to the boat is $29^\\circ$. How far is the boat from the base of the cliff, in meters? (Round to the nearest whole number.)', NULL, $lyceon_json$[{"key":"A","text":"$132$"},{"key":"B","text":"$35$"},{"key":"C","text":"$84$"},{"key":"D","text":"$40$"}]$lyceon_json$::jsonb, 'A', NULL, E'The angle of depression from the top of the cliff equals the angle of elevation from the boat. In the right triangle, the cliff height $73$ m is opposite the $29^\\circ$ angle, and the horizontal distance $d$ is adjacent. So $\\tan(29^\\circ) = \\frac{73}{d}$, giving $d = \\frac{73}{\\tan(29^\\circ)} = \\frac{73}{0.5543} \\approx 132$ meters. The distractor $35$ comes from computing $73 \\cdot \\sin(29^\\circ) \\approx 35.4$, using sine instead of tangent. The distractor $84$ results from computing $\\frac{73}{\\cos(29^\\circ)}$ or using an incorrect angle. The distractor $40$ comes from computing $73 \\cdot \\tan(29^\\circ) \\approx 40.5$, multiplying instead of dividing.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PT9HCN', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $p$ has the equation $4x - 7y = 28$. Line $q$ is perpendicular to line $p$ and passes through the point $(-5, 2)$. What is the $y$-intercept of line $q$?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{27}{4}$"},{"key":"B","text":"$\\frac{27}{4}$"},{"key":"C","text":"$-\\frac{43}{4}$"},{"key":"D","text":"$\\frac{4}{7}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rewriting line $p$: $y = \\frac{4}{7}x - 4$, so its slope is $\\frac{4}{7}$. The perpendicular slope is $-\\frac{7}{4}$. Using point-slope with $(-5, 2)$: $y - 2 = -\\frac{7}{4}(x + 5)$, giving $y = -\\frac{7}{4}x - \\frac{35}{4} + \\frac{8}{4} = -\\frac{7}{4}x - \\frac{27}{4}$. The $y$-intercept is $-\\frac{27}{4}$. The distractor $\\frac{27}{4}$ drops the negative sign. The distractor $-\\frac{43}{4}$ subtracts $2$ instead of adding it, computing $-\\frac{35}{4} - \\frac{8}{4}$. The distractor $\\frac{4}{7}$ is the slope of the original line, confusing slope with intercept.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QER3Y4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A county health department surveyed $1{,}400$ randomly selected adults and found that those who reported eating breakfast daily had lower rates of heart disease than those who reported skipping breakfast. A newspaper headline stated: "Eating breakfast every day prevents heart disease." Which of the following best evaluates the newspaper''s claim?', NULL, $lyceon_json$[{"key":"A","text":"The claim is supported because the sample was randomly selected and large."},{"key":"B","text":"The claim is not supported because the study was observational and confounding variables, such as overall diet quality and exercise habits, could explain the association."},{"key":"C","text":"The claim is supported because $1{,}400$ adults is a sufficient sample size to prove causation."},{"key":"D","text":"The claim is not supported because the survey did not include children."}]$lyceon_json$::jsonb, 'B', NULL, E'The study is observational — participants were not randomly assigned to eat or skip breakfast. While random selection of the sample supports generalizability to the population, it does not establish causation. Confounding variables such as overall diet quality, exercise habits, and socioeconomic status could explain the observed association. The assertion that random selection and large size support the causal claim conflates random selection (which aids representativeness) with random assignment (which supports causation). The claim that a sample of $1{,}400$ is sufficient to prove causation confuses sample size with study design — no sample size alone can establish causation in an observational study. The objection that the survey did not include children identifies a real limitation of generalizability but does not address the core flaw in the causal claim.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QURW7Y', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A shirt originally costs $\\$45$. It is on sale for $20\\%$ off. What is the sale price of the shirt?', NULL, $lyceon_json$[{"key":"A","text":"$\\$9$"},{"key":"B","text":"$\\$25$"},{"key":"C","text":"$\\$36$"},{"key":"D","text":"$\\$54$"}]$lyceon_json$::jsonb, 'C', NULL, E'The discount is $20\\%$ of $\\$45$, which is $0.20 \\times 45 = \\$9$. The sale price is $45 - 9 = \\$36$. The value $\\$9$ is the discount amount, not the sale price, reflecting only partial reasoning. The value $\\$25$ results from subtracting $20$ from $45$ instead of computing the percentage. The value $\\$54$ comes from adding the discount to the original price instead of subtracting it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2R32XX6', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A carpenter charges a flat fee of \\$47 plus \\$29 per hour for a repair job. If a customer has a budget of no more than \\$221, which inequality represents the number of hours \\(h\\) the carpenter can work, and what is the maximum whole number of hours?', NULL, $lyceon_json$[{"key":"A","text":"\\(29h + 47 \\leq 221\\); 5 hours"},{"key":"B","text":"\\(29h + 47 \\leq 221\\); 6 hours"},{"key":"C","text":"\\(29h - 47 \\leq 221\\); 9 hours"},{"key":"D","text":"\\(47h + 29 \\leq 221\\); 4 hours"}]$lyceon_json$::jsonb, 'B', NULL, E'The total cost is \\(29h + 47\\), which must be at most \\$221. Solving \\(29h + 47 \\leq 221\\) gives \\(29h \\leq 174\\), so \\(h \\leq 6\\). The maximum whole number of hours is 6. The option pairing the correct inequality with 5 hours makes an arithmetic error when dividing 174 by 29. The option using \\(29h - 47 \\leq 221\\) subtracts the flat fee instead of adding it, yielding an inflated result of 9 hours. The option using \\(47h + 29 \\leq 221\\) swaps the hourly rate and flat fee, producing 4 hours.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ROF7QK', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, one leg measures $9$ and the hypotenuse measures $41$. What is the length of the other leg?', NULL, $lyceon_json$[{"key":"A","text":"$32$"},{"key":"B","text":"$40$"},{"key":"C","text":"$42$"},{"key":"D","text":"$50$"}]$lyceon_json$::jsonb, 'B', NULL, E'Using the Pythagorean theorem: $b = \\sqrt{41^2 - 9^2} = \\sqrt{1681 - 81} = \\sqrt{1600} = 40$. The distractor $32$ comes from subtracting the values directly ($41 - 9$) instead of using the Pythagorean theorem. The distractor $42$ results from a computational error such as miscalculating $\\sqrt{1681 - 81}$. The distractor $50$ arises from adding instead of subtracting under the radical ($\\sqrt{41^2 + 9^2}$) and rounding.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SD9KW1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A line of best fit for a data set is given by $y = -2.3x + 58.7$. According to this model, what is the predicted value of $y$ when $x = 13$?', NULL, $lyceon_json$[{"key":"A","text":"$28.8$"},{"key":"B","text":"$88.6$"},{"key":"C","text":"$29.9$"},{"key":"D","text":"$31.1$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 13$: $y = -2.3(13) + 58.7 = -29.9 + 58.7 = 28.8$. The value $88.6$ results from adding $29.9 + 58.7$ instead of subtracting, ignoring the negative coefficient. The value $29.9$ comes from computing $2.3 \\times 13 = 29.9$ but forgetting to combine it with the intercept. The value $31.1$ results from a multiplication error such as computing $2.3 \\times 12 = 27.6$ and then $58.7 - 27.6 = 31.1$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2THJO5N', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'The ages of $6$ participants are $19, 23, 27, 27, 31, 43$. If the oldest participant ($43$) is replaced by a new participant aged $33$, which of the following correctly describes the change?', NULL, $lyceon_json$[{"key":"A","text":"The mean decreases and the median stays the same."},{"key":"B","text":"The mean stays the same and the median increases."},{"key":"C","text":"Both the mean and the median decrease."},{"key":"D","text":"The mean increases and the median stays the same."}]$lyceon_json$::jsonb, 'A', NULL, E'Original sum: $19 + 23 + 27 + 27 + 31 + 43 = 170$, mean $= \\frac{170}{6} \\approx 28.33$. New sum: $170 - 43 + 33 = 160$, new mean $= \\frac{160}{6} \\approx 26.67$, so the mean decreases. The median of the original sorted set is $\\frac{27 + 27}{2} = 27$. The new sorted set is $19, 23, 27, 27, 31, 33$, and the median is still $\\frac{27 + 27}{2} = 27$, so the median stays the same. Claiming the mean stays the same ignores the lower replacement value. Claiming both decrease incorrectly assumes the median is affected by the change in the largest value. Claiming the mean increases reverses the direction of the change.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TUG4GF', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'Triangle $JKL$ is similar to triangle $MNP$. In triangle $JKL$, $JK = 14$, $KL = 21$, and $JL = 35$. If $MN = 6$, what is the length of $NP$?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$15$"},{"key":"C","text":"$12$"},{"key":"D","text":"$13$"}]$lyceon_json$::jsonb, 'A', NULL, E'Since the triangles are similar with corresponding vertices in order ($J \\leftrightarrow M$, $K \\leftrightarrow N$, $L \\leftrightarrow P$), the ratio of corresponding sides is constant. The scale factor is $\\frac{MN}{JK} = \\frac{6}{14} = \\frac{3}{7}$. Therefore $NP = KL \\times \\frac{3}{7} = 21 \\times \\frac{3}{7} = 9$. The distractor $15$ incorrectly uses $JL$ instead of $KL$: $35 \\times \\frac{3}{7} = 15$, matching the wrong pair of corresponding sides. The distractor $12$ may result from computing $\\frac{6}{14} \\times 28$ or incorrectly doubling the scale factor. The distractor $13$ comes from an arithmetic error in the proportion.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V61UDK', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle in the $xy$-plane has equation $(x + 7)^2 + (y - 4)^2 = 81$. What is the radius of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$81$"},{"key":"C","text":"$\\frac{81}{2}$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'A', NULL, E'The standard form of a circle is $(x - h)^2 + (y - k)^2 = r^2$. Here $r^2 = 81$, so $r = \\sqrt{81} = 9$. The distractor $81$ confuses $r^2$ with $r$, reporting the squared radius. The distractor $\\frac{81}{2}$ incorrectly halves the right side, perhaps confusing radius with diameter in reverse. The distractor $7$ reads the coefficient from the $(x + 7)$ term, confusing a center coordinate with the radius.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VWA56I', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'After a $15\\%$ increase, the population of a town is $6{,}670$. What was the population before the increase?', NULL, $lyceon_json$[{"key":"A","text":"$5{,}670$"},{"key":"B","text":"$5{,}800$"},{"key":"C","text":"$5{,}669.50$"},{"key":"D","text":"$7{,}670.50$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let the original population be $p$. After a $15\\%$ increase: $1.15p = 6{,}670$, so $p = \\frac{6{,}670}{1.15} = 5{,}800$. The value $5{,}670$ results from subtracting $1{,}000$ from $6{,}670$ as an estimate rather than computing the exact percentage. The value $5{,}669.50$ comes from computing $15\\%$ of $6{,}670$ and subtracting ($6{,}670 - 1{,}000.50$), which applies the percentage to the final value instead of the original. The value $7{,}670.50$ results from adding $15\\%$ of $6{,}670$ to $6{,}670$, reversing the direction of the problem.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XIW8Y9', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A data set contains the values $2, 5, 8, 11, 14$. What is the median of this data set?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$8$"},{"key":"C","text":"$9$"},{"key":"D","text":"$11$"}]$lyceon_json$::jsonb, 'B', NULL, E'With $5$ values in ascending order, the median is the middle (third) value, which is $8$. The value $5$ is the second value, not the median, reflecting a miscount of the middle position. The value $9$ results from computing the mean ($\\frac{40}{5} = 8$ is actually correct, but $\\frac{2 + 5 + 8 + 11 + 14}{5} = \\frac{40}{5} = 8$; the distractor $9$ would come from an arithmetic error such as summing to $45$ instead of $40$). The value $11$ is the fourth value, selected by miscounting the middle position from the wrong end.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YICYZG', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a diameter of $26$. What is the area of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$169\\pi$"},{"key":"B","text":"$676\\pi$"},{"key":"C","text":"$26\\pi$"},{"key":"D","text":"$13\\pi$"}]$lyceon_json$::jsonb, 'A', NULL, E'The radius is half the diameter: $r = \\frac{26}{2} = 13$. The area is $\\pi r^2 = \\pi(13)^2 = 169\\pi$. The distractor $676\\pi$ uses the diameter instead of the radius in the area formula ($\\pi \\cdot 26^2$). The distractor $26\\pi$ computes the circumference ($\\pi d$) instead of the area. The distractor $13\\pi$ uses the radius but applies the circumference formula ($\\pi r$) rather than squaring.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z6AJD2', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'A circle has center $(2, -5)$ and passes through the point $(11, 7)$. What is the equation of this circle?', NULL, $lyceon_json$[{"key":"A","text":"$(x - 2)^2 + (y + 5)^2 = 225$"},{"key":"B","text":"$(x - 2)^2 + (y + 5)^2 = 15$"},{"key":"C","text":"$(x + 2)^2 + (y - 5)^2 = 225$"},{"key":"D","text":"$(x - 2)^2 + (y + 5)^2 = 293$"}]$lyceon_json$::jsonb, 'A', NULL, E'The radius is the distance from the center $(2, -5)$ to the point $(11, 7)$: $r = \\sqrt{(11 - 2)^2 + (7 - (-5))^2} = \\sqrt{9^2 + 12^2} = \\sqrt{81 + 144} = \\sqrt{225} = 15$. The equation is $(x - 2)^2 + (y + 5)^2 = 225$. The distractor $(x - 2)^2 + (y + 5)^2 = 15$ uses the radius instead of the radius squared. The distractor $(x + 2)^2 + (y - 5)^2 = 225$ reverses the signs of the center coordinates. The distractor with $293$ comes from a computational error such as squaring $13$ instead of $12$ for the $y$-difference: $81 + 169 = 250$, or another arithmetic mistake yielding $293$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z7FU1H', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A bag contains $7$ red marbles and $11$ blue marbles. If one marble is selected at random, what is the probability that it is red?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{18}$"},{"key":"B","text":"$\\frac{11}{18}$"},{"key":"C","text":"$\\frac{7}{11}$"},{"key":"D","text":"$\\frac{11}{7}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of marbles is $7 + 11 = 18$. The probability of selecting a red marble is $\\frac{7}{18}$. The distractor $\\frac{11}{18}$ results from selecting the count of blue marbles instead of red (misreading the question). The distractor $\\frac{7}{11}$ uses the count of blue marbles as the denominator rather than the total, reflecting a misunderstanding of basic probability. The distractor $\\frac{11}{7}$ inverts the ratio and exceeds $1$, which is impossible for a probability.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZISHVZ', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $5x^4 \\cdot 3x^7$?', NULL, $lyceon_json$[{"key":"A","text":"$15x^{11}$"},{"key":"B","text":"$15x^{28}$"},{"key":"C","text":"$8x^{11}$"},{"key":"D","text":"$8x^{28}$"}]$lyceon_json$::jsonb, 'A', NULL, E'When multiplying monomials, multiply the coefficients and add the exponents: $5 \\cdot 3 = 15$ and $x^{4+7} = x^{11}$, giving $15x^{11}$. The distractor $15x^{28}$ results from multiplying the exponents ($4 \\times 7 = 28$) instead of adding them, reflecting a fundamental misunderstanding of the exponent rule for multiplication. The distractor $8x^{11}$ results from adding the coefficients ($5 + 3 = 8$) instead of multiplying them. The distractor $8x^{28}$ combines both errors: adding coefficients and multiplying exponents.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
