INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW211KIAF', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The architect argued that if the city council _____ the proposed zoning amendment at next month''s session, the resulting restrictions will delay construction of the community center by at least fourteen months.', $lyceon_json$[{"key":"A","text":"will approve"},{"key":"B","text":"would approve"},{"key":"C","text":"approves"},{"key":"D","text":"had approved"}]$lyceon_json$::jsonb, 'C', NULL, E'In a first conditional construction expressing a real future possibility, Standard English requires the present tense in the "if" clause paired with the future tense in the main clause. The present-tense verb "approves" correctly completes the conditional: "if the city council approves... the resulting restrictions will delay." Using "will approve" in the "if" clause is nonstandard because the future tense should not appear in the conditional clause of a first conditional. The modal "would approve" creates a mixed conditional that does not match the indicative "will delay" in the main clause. The past perfect "had approved" implies a past counterfactual situation, which contradicts the future time reference established by "at next month''s session."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22VTKT9', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the passage, "arrested" most nearly means', E'During the late stages of the experiment, the introduction of a calcium-channel blocker arrested the rapid proliferation of the cultured cells, allowing the research team to isolate individual colonies for genetic sequencing.', $lyceon_json$[{"key":"A","text":"seized"},{"key":"B","text":"halted"},{"key":"C","text":"accelerated"},{"key":"D","text":"documented"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes a chemical agent stopping cell proliferation so colonies could be isolated. "Halted" correctly captures this meaning of bringing a process to a stop. "Seized" means to grab or take possession of a physical object, which is incoherent when applied to a biological process like proliferation. "Accelerated" means to speed up, which is the opposite of what the passage describes — the blocker stopped proliferation, it did not increase it. "Documented" means to record or create a written account, which contradicts the passage''s description of a chemical intervention that changes the cells'' behavior.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
