INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW256ROQX', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the overall structure of the passage?', E'The fruit fly Drosophila melanogaster completes its entire life cycle in roughly ten days at room temperature, a trait that made it indispensable to geneticists as early as 1910. Yet speed alone does not explain its dominance in laboratory research. The organism''s genome, fully sequenced by 2000, contains approximately 14,000 genes — roughly 60 percent of which have recognizable counterparts in humans. This genomic overlap means that findings about gene regulation, cell signaling, and developmental timing in Drosophila frequently translate, with appropriate caution, to hypotheses about human biology. The fly, in other words, is not merely convenient; it is informative.', $lyceon_json$[{"key":"A","text":"It presents two competing theories about an organism's usefulness and reconciles them"},{"key":"B","text":"It traces the historical development of a research methodology from its origins to the present"},{"key":"C","text":"It acknowledges a common explanation for a phenomenon and then argues that a deeper reason is more significant"},{"key":"D","text":"It refutes a claim about a model organism by presenting contradictory genetic evidence"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage begins by noting the fly''s fast life cycle (a common explanation for its laboratory dominance), then pivots with "Yet speed alone does not explain" to argue that genomic overlap with humans is the deeper, more significant reason. This structure — acknowledging a familiar explanation and then arguing for a more important one — matches the correct choice. The passage does not present two competing theories that need reconciling; it supplements one explanation with a more significant one. It does not trace the historical development of a methodology — it mentions dates only incidentally. It does not refute the claim about the fly''s fast life cycle; it accepts that trait and argues something additional is more important.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW277CAN4', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'A student claims that the architect''s design philosophy prioritized the emotional experience of building occupants over structural innovation. Which quotation from the passage, if any, most effectively supports this claim?', E'Architect Tomoko Ishida gained international recognition in the early 2010s for her residential designs in Sendai, Japan. In a 2014 interview, Ishida explained her approach: "I begin every project by asking how the person living in this space should feel at different times of day. The engineering follows from that—not the other way around." Critics noted that Ishida''s buildings featured no unusual structural techniques; her floor plans used conventional post-and-beam construction. What distinguished her work was the meticulous calibration of natural light: her signature hallway windows were angled at precisely 7.5 degrees off vertical so that morning sunlight would reach interior rooms that typically remain dim in standard Japanese residential layouts. Ishida stated in 2017, "A home that solves an engineering problem nobody asked about is just a monument to the architect. A home that makes you feel calm at breakfast—that is architecture."', $lyceon_json$[{"key":"A","text":"\"Critics noted that Ishida's buildings featured no unusual structural techniques; her floor plans used conventional post-and-beam construction.\""},{"key":"B","text":"\"I begin every project by asking how the person living in this space should feel at different times of day. The engineering follows from that—not the other way around.\""},{"key":"C","text":"\"Her signature hallway windows were angled at precisely 7.5 degrees off vertical so that morning sunlight would reach interior rooms that typically remain dim in standard Japanese residential layouts.\""},{"key":"D","text":"\"Architect Tomoko Ishida gained international recognition in the early 2010s for her residential designs in Sendai, Japan.\""}]$lyceon_json$::jsonb, 'B', NULL, E'The claim is that Ishida prioritized occupants'' emotional experience over structural innovation. The quotation where Ishida says she begins by asking how the person should feel and that engineering follows from that directly articulates this priority in her own words. The quotation about critics noting conventional construction supports only half the claim—it shows she did not pursue structural novelty—but does not establish that emotional experience was prioritized instead. The quotation about windows angled at 7.5 degrees describes a specific design detail related to light, which connects to occupant experience indirectly but does not articulate the overarching philosophy of prioritizing emotion over structure. The quotation about international recognition states a biographical fact and says nothing about her design philosophy.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27TW0OL', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Displayed prominently in the vestibule of the nineteenth-century municipal courthouse, which today serves as the county''s historical society headquarters, _____ a series of seventeen oil portraits depicting the judges who presided over the region''s landmark water-rights tribunal of 1883.', $lyceon_json$[{"key":"A","text":"hang"},{"key":"B","text":"are hanging"},{"key":"C","text":"have hung"},{"key":"D","text":"hangs"}]$lyceon_json$::jsonb, 'D', NULL, E'This sentence uses inverted word order: the subject "a series of seventeen oil portraits" follows the verb rather than preceding it. The head noun of the subject is "series," which is singular, so the verb must also be singular. The singular verb "hangs" correctly agrees with "a series." The plural verb "hang" incorrectly treats "portraits" as the subject. The plural progressive "are hanging" also fails to agree with the singular "series." The plural present perfect "have hung" similarly misidentifies the plural noun "portraits" as the subject rather than the singular "series."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AV3216', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the passage, "struck" most nearly means', E'A researcher studying migratory patterns of Arctic terns noticed that the birds consistently altered their flight paths near coastal storms. It struck her that the detours, rather than being random evasions, followed predictable electromagnetic contours generated by the storm systems themselves.', $lyceon_json$[{"key":"A","text":"collided with"},{"key":"B","text":"occurred to"},{"key":"C","text":"punished"},{"key":"D","text":"hammered"}]$lyceon_json$::jsonb, 'B', NULL, E'In the passage, the researcher realizes something about the birds'' flight paths — the detours follow predictable contours. "Occurred to" captures this sense of a sudden realization. "Collided with" refers to physical impact, which is incoherent when applied to a person having a realization. "Punished" refers to imposing a penalty, which has no connection to the cognitive event described. "Hammered" means to strike repeatedly with force, which does not apply to the mental event in the passage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BY221Q', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the function of the passage?', E'Conventional accounts of the Dust Bowl attribute the ecological catastrophe primarily to drought conditions that persisted across the Great Plains throughout the 1930s. However, historian Maren Kingsley contends that federal land-distribution policies of the 1910s, which incentivized homesteaders to convert vast tracts of native grassland to wheat cultivation, created the preconditions for topsoil loss on a continental scale. Without those policies, Kingsley argues, the droughts of the 1930s would have produced hardship but not the wholesale destruction of arable land that defined the era.', $lyceon_json$[{"key":"A","text":"To chronicle the sequence of federal land policies enacted in the early twentieth century"},{"key":"B","text":"To argue that drought played no meaningful role in the Dust Bowl"},{"key":"C","text":"To introduce a historian's challenge to a widely held explanation for an environmental disaster"},{"key":"D","text":"To describe the agricultural practices that were common on the Great Plains during the 1930s"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage first states the conventional view (drought caused the Dust Bowl) and then introduces Kingsley''s contrasting argument that federal land policies created the preconditions. Its function is to introduce a historian''s challenge to a widely held explanation. Chronicling the sequence of federal land policies misidentifies the function — the passage mentions policies only as part of Kingsley''s argument, not to provide a policy timeline. The claim that drought played no meaningful role overstates Kingsley''s position; she acknowledges drought would have caused hardship but argues policies made it catastrophic. Describing common agricultural practices misreads the passage''s purpose — farming practices are mentioned only in service of Kingsley''s causal argument.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EJ5XO4', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which quotation from the passage most directly supports the claim that the city''s new composting program has reduced landfill waste?', E'In March 2023, the city of Valleybrook, Oregon, launched a curbside composting program requiring all households to separate organic waste from general refuse. City officials hoped the program would extend the operational lifespan of the Ridgemont landfill, which was projected to reach capacity by 2031. By the end of the program''s first year, municipal records showed that the tonnage of waste delivered to Ridgemont had declined by 18 percent compared to the previous twelve-month period. Participation surveys indicated that 74 percent of households were consistently using the composting bins. The composted material was processed at a facility in nearby Ashton and sold to regional farms as soil amendment.', $lyceon_json$[{"key":"A","text":"\"City officials hoped the program would extend the operational lifespan of the Ridgemont landfill, which was projected to reach capacity by 2031.\""},{"key":"B","text":"\"By the end of the program's first year, municipal records showed that the tonnage of waste delivered to Ridgemont had declined by 18 percent compared to the previous twelve-month period.\""},{"key":"C","text":"\"Participation surveys indicated that 74 percent of households were consistently using the composting bins.\""},{"key":"D","text":"\"The composted material was processed at a facility in nearby Ashton and sold to regional farms as soil amendment.\""}]$lyceon_json$::jsonb, 'B', NULL, E'The claim is that the composting program reduced landfill waste. The quotation about the tonnage of waste declining by 18 percent provides direct, measurable evidence of reduced landfill waste. The quotation about officials'' hopes describes a goal, not an outcome, and therefore does not demonstrate that landfill waste was actually reduced. The quotation about 74 percent household participation shows engagement with the program but does not itself quantify any reduction in landfill waste. The quotation about composted material being sold to farms describes what happens to the organic waste after processing, which is tangential to whether landfill-bound waste decreased.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FBAFPW', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of rare geological specimens housed in the university''s natural history museum _____ open to the public every Saturday morning from March through November.', $lyceon_json$[{"key":"A","text":"are"},{"key":"B","text":"is"},{"key":"C","text":"were"},{"key":"D","text":"have been"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the sentence is "collection," which is singular. The prepositional phrase "of rare geological specimens housed in the university''s natural history museum" modifies "collection" but does not change its number. The singular verb "is" correctly agrees with the singular subject "collection." The plural verb "are" incorrectly agrees with the nearest noun "specimens" rather than the actual subject. The past-tense plural verb "were" is wrong in both number and tense, since the sentence describes a current, recurring schedule. The plural verb phrase "have been" also fails to agree with the singular subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FZBGLN', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'When a deep-sea diver encounters an unfamiliar species at extreme depths, _____ must document the organism''s size, coloration, and behavior before ascending, since the specimen may not survive the pressure change involved in retrieval.', $lyceon_json$[{"key":"A","text":"you"},{"key":"B","text":"the diver"},{"key":"C","text":"we"},{"key":"D","text":"it"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence introduces its subject as "a deep-sea diver" in the third person singular. The noun phrase "the diver" maintains consistent person and number throughout the sentence, clearly referring back to the antecedent. The pronoun "you" shifts from third person to second person, creating an inconsistent point of view. The pronoun "we" shifts to first person plural, which is similarly inconsistent with the third-person introduction. The pronoun "it" is inappropriate because it refers to a person, not an inanimate object.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GHR558', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice most accurately describes the relationship between the two findings discussed in the passage?', E'Neuroscientist Elara Mäkinen''s 2022 study at the University of Turku examined how bilingual individuals process numerical information differently depending on which language they are using. Mäkinen found that when Finnish-Swedish bilinguals performed arithmetic in their first language (Finnish), their response times were 23 percent faster than when they performed the same operations in Swedish, even though all participants reported equal fluency in both languages. Intriguingly, this advantage disappeared entirely for problems involving estimation rather than exact calculation. When asked to approximate quantities—such as judging whether 847 plus 319 is closer to 1,100 or 1,200—participants performed identically in both languages. Mäkinen hypothesized that exact arithmetic relies on language-specific verbal routines memorized during early education, while estimation draws on a language-independent spatial-quantitative system.', $lyceon_json$[{"key":"A","text":"The first finding establishes that bilinguals are generally faster at arithmetic in their first language, while the second finding reveals an exception for estimation tasks that suggests different cognitive mechanisms underlie exact and approximate calculation."},{"key":"B","text":"The first finding demonstrates that self-reported fluency is an unreliable measure of language ability, while the second finding confirms that estimation tasks are inherently easier than exact arithmetic."},{"key":"C","text":"The first finding shows that Finnish is a more efficient language for mathematical processing than Swedish, while the second finding indicates that this efficiency extends only to certain types of problems."},{"key":"D","text":"The first finding suggests that early education determines arithmetic ability, while the second finding proves that estimation is a skill acquired independently of formal schooling."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents two findings: bilinguals are faster at exact arithmetic in their first language, and this advantage vanishes for estimation. The option describing the first finding as establishing a first-language speed advantage and the second as revealing an exception that implicates different cognitive mechanisms accurately captures this relationship and aligns with Mäkinen''s hypothesis about language-specific verbal routines versus a language-independent system. The option about self-reported fluency being unreliable misreads the passage—the fluency detail provides context but is not itself the finding, and nothing states estimation is inherently easier. The option claiming Finnish is more efficient than Swedish misidentifies the effect as a property of the Finnish language rather than of first-language processing generally. The option about early education determining arithmetic ability and estimation being acquired without schooling overextends Mäkinen''s hypothesis, which connects early education to language-specific memorization but never claims estimation is independent of formal schooling.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2H4SYKB', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the passage?', E'A team of marine biologists at the University of Bergen recently documented an unexpected behavioral pattern among Atlantic hagfish. While hagfish have long been regarded as passive scavengers that feed exclusively on dead or dying organisms on the ocean floor, the researchers observed hagfish actively burrowing into the sediment to hunt polychaete worms. Over a fourteen-month observation period using remotely operated cameras at a depth of 370 meters in the Norwegian Sea, the team recorded 213 instances of hagfish pursuing live prey. The findings challenge the prevailing characterization of hagfish as obligate scavengers and suggest that their ecological role in deep-sea food webs may be more complex than previously understood.', $lyceon_json$[{"key":"A","text":"Atlantic hagfish are more difficult to study than other deep-sea organisms because of the extreme depths at which they live."},{"key":"B","text":"Recent observations indicate that Atlantic hagfish actively hunt live prey, contradicting their traditional classification as purely passive scavengers."},{"key":"C","text":"Marine biologists have developed new camera technology that allows them to monitor deep-sea organisms more effectively than before."},{"key":"D","text":"Polychaete worms are a primary food source for most deep-sea scavengers in the Norwegian Sea."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage centers on the discovery that Atlantic hagfish hunt live prey, overturning their classification as obligate scavengers. The option stating that recent observations show hagfish actively hunting live prey captures this main idea. The option about difficulty of study misreads the passage, which mentions depth only as context for the observation setup, not as a barrier to research. The option about camera technology focuses on a minor detail (the remotely operated cameras) rather than the passage''s central finding. The option about polychaete worms being a primary food source for most deep-sea scavengers extends far beyond what the passage claims—it mentions only hagfish consuming polychaete worms, not other species.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HS5O6K', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Based on the passage, what can most reasonably be inferred about the relationship between coral bleaching frequency and reef recovery capacity?', E'Marine ecologist Priya Chandrasekaran studied 19 coral reef systems in the Andaman Sea between 2009 and 2023. Her data showed that reefs experiencing bleaching events spaced at least seven years apart recovered to 85–92 percent of their pre-bleaching coral cover within five years. However, reefs that experienced bleaching events at intervals of four years or fewer showed a markedly different trajectory: after the second event, these reefs recovered to only 40–55 percent of their original cover, and after a third closely spaced event, recovery plateaued at 15–25 percent regardless of the time allowed. Chandrasekaran noted that the reefs failing to recover fully were not colonized by new coral but instead became dominated by macroalgae, which outcompeted coral larvae for substrate. She observed that once macroalgae established dense coverage exceeding 60 percent of available substrate, no reef in her dataset had returned to coral dominance within the study period.', $lyceon_json$[{"key":"A","text":"Coral reefs can recover indefinitely from bleaching events as long as water temperatures eventually return to normal levels."},{"key":"B","text":"When bleaching events occur too frequently, reefs may cross a threshold beyond which coral recovery becomes unlikely because competing organisms occupy the available space."},{"key":"C","text":"Macroalgae growth is the primary cause of coral bleaching in the Andaman Sea, creating a feedback loop that accelerates reef decline."},{"key":"D","text":"Coral reefs that experience only a single bleaching event are permanently immune to future bleaching-related damage."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage shows that closely spaced bleaching events produce diminishing recovery, culminating in macroalgae dominance that prevents coral from reclaiming substrate. The option describing a threshold beyond which recovery becomes unlikely because competing organisms occupy space accurately synthesizes these findings into a reasonable inference about the relationship between bleaching frequency and recovery capacity. The option about indefinite recovery contradicts the passage''s central finding that closely spaced events progressively reduce recovery potential. The option claiming macroalgae causes bleaching reverses the causal relationship described in the passage—bleaching weakens coral, and macroalgae then colonizes the vacated substrate; macroalgae is a consequence, not a cause, of bleaching. The option about permanent immunity after a single event has no basis in the passage, which discusses recovery rates but never suggests that surviving one event confers protection against future events.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2J39KV8', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'During the late nineteenth century, Brazilian composer Chiquinha Gonzaga challenged prevailing norms by incorporating Afro-Brazilian rhythmic patterns into salon music, a genre then dominated by European conventions. Many of her contemporaries dismissed these compositions as incompatible with the refinement expected of parlor entertainment. _______ Gonzaga''s polka-maxixe hybrid "Atraente," published in 1877, became so widely performed in Rio de Janeiro''s salons that rival composers began adopting similar rhythmic structures, effectively validating the very fusion they had initially rejected.', $lyceon_json$[{"key":"A","text":"In addition,"},{"key":"B","text":"That is,"},{"key":"C","text":"Regardless,"},{"key":"D","text":"On the other hand,"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence before the blank describes contemporaries dismissing Gonzaga''s compositions. The sentence after the blank shows that despite this dismissal, her work became widely popular and was even imitated by the same critics. "Regardless," correctly signals that the outcome occurred despite the opposition described previously. "In addition," would merely add information without capturing the tension between the dismissal and the subsequent success. "That is," signals a restatement or clarification, but the sentence provides a new development rather than restating the dismissal. "On the other hand," introduces a contrasting perspective in a balanced comparison, but the passage is not presenting two equally weighted sides; it is showing that opposition was overridden by success.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LYSXNL', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Archaeologist Elif Batuman''s excavations at the Phrygian site of Gordion in central Anatolia have revealed that the city''s distinctive ceramic style, long assumed to have originated locally, bears striking chemical similarities to pottery produced in workshops near Lake Van, over nine hundred kilometers to the east. _______ Batuman does not conclude that Gordion''s potters simply copied eastern techniques. Her analysis of kiln residues shows that Gordion artisans combined the imported clay formulations with a firing method unique to the western Anatolian plateau, producing a hybrid tradition that had no exact counterpart at either source.', $lyceon_json$[{"key":"A","text":"For instance,"},{"key":"B","text":"Similarly,"},{"key":"C","text":"However,"},{"key":"D","text":"Consequently,"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentences before the blank establish that Gordion''s ceramics share chemical similarities with eastern pottery, which might lead a reader to expect that the potters copied eastern techniques. The sentence after the blank pivots away from that expectation, stating that Batuman does not draw that conclusion. "However," correctly signals this contrast between the apparent implication of the chemical evidence and Batuman''s more nuanced interpretation. "For instance," would introduce an example of a previously stated generalization, but the sentence does not exemplify anything; it introduces a counterpoint. "Similarly," implies a parallel relationship, but the sentence after the blank contradicts, rather than parallels, the expected conclusion. "Consequently," implies the sentence follows as a logical result, but refusing to conclude simple copying is a departure from, not a consequence of, the chemical similarity evidence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ME7WQ0', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Researchers at the Kyoto Primate Institute observed that one chimpanzee, a seventeen-year-old female named Hana who had been raised in a bilingual signing environment _____ consistently outperformed her peers on tasks requiring short-term spatial memory.', $lyceon_json$[{"key":"A","text":"environment;"},{"key":"B","text":"environment:"},{"key":"C","text":"environment"},{"key":"D","text":"environment,"}]$lyceon_json$::jsonb, 'D', NULL, E'The phrase "a seventeen-year-old female named Hana who had been raised in a bilingual signing environment" is a nonrestrictive appositive renaming "one chimpanzee." Because this appositive is introduced by a comma after "chimpanzee," it must be closed with a matching comma after "environment" to properly set off the parenthetical element. A comma after "environment" correctly closes the appositive and allows the main clause to continue with "consistently outperformed." A semicolon after "environment" would incorrectly signal the boundary between two independent clauses, splitting the subject from its verb. A colon after "environment" would incorrectly introduce a list or explanation where none follows. Omitting punctuation entirely after "environment" fails to close the nonrestrictive appositive, leaving the sentence structure unresolved.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2N3LUF7', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing an article about an innovative agricultural technique and wants to emphasize the environmental advantages of the technique over conventional methods. Which choice most effectively uses information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2N48H61', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'A researcher argues that the decline in monarch butterfly populations along the eastern migratory corridor is driven primarily by loss of milkweed habitat rather than by climate variability. Which finding from the passage, if incorporated into the researcher''s argument, would most strengthen it?', E'Between 2006 and 2022, entomologists tracked monarch butterfly populations at 43 overwintering sites in the mountains of Michoacán, Mexico. The total area occupied by monarch colonies declined from 6.87 hectares in 2006 to 2.21 hectares in 2022. During the same period, satellite imagery analysis showed that milkweed coverage in the midwestern United States—the primary breeding ground for eastern monarchs—decreased by 31 percent, largely due to the expansion of herbicide-tolerant crop varieties that eliminated milkweed from agricultural margins. Temperature and precipitation records for the migratory corridor showed no statistically significant trend over the study period; seasonal averages remained within 1.2 standard deviations of the 1980–2005 baseline. A separate 2020 study found that monarchs raised in controlled environments with adequate milkweed displayed survival and reproduction rates comparable to those documented in the 1990s, before the population decline accelerated.', $lyceon_json$[{"key":"A","text":"The total area occupied by monarch colonies declined from 6.87 hectares in 2006 to 2.21 hectares in 2022."},{"key":"B","text":"Temperature and precipitation records for the migratory corridor showed no statistically significant trend over the study period."},{"key":"C","text":"Satellite imagery analysis showed that milkweed coverage in the midwestern United States decreased by 31 percent."},{"key":"D","text":"Monarchs raised in controlled environments with adequate milkweed displayed survival and reproduction rates comparable to those documented in the 1990s."}]$lyceon_json$::jsonb, 'D', NULL, E'The researcher''s argument has two components: milkweed loss is the primary driver, and climate variability is not. The finding that monarchs with adequate milkweed reproduce at historical rates most strengthens this argument because it demonstrates that when the milkweed variable is controlled for, the decline disappears—directly implicating milkweed loss as the cause. The finding about colony area declining documents the decline itself but does not distinguish between possible causes. The finding about stable temperature and precipitation weakens the climate explanation but does not positively strengthen the milkweed explanation—it only removes an alternative. The finding about milkweed coverage decreasing by 31 percent establishes correlation between milkweed loss and population decline but does not demonstrate causation the way the controlled-environment study does.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NHKYWN', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Based on the passage, it can most reasonably be inferred that Lindström views traditional preservation methods as', E'Textile conservator Margit Lindström has spent over two decades restoring medieval tapestries housed in Scandinavian museums. In a 2023 lecture at the Nordic Conservation Institute, Lindström described the tension between preserving a tapestry''s structural integrity and maintaining its visual character. "The standard approach," she explained, "is to mount a deteriorating tapestry on a linen support fabric that bears the weight of the weakened fibers. This prevents further tearing, but it also flattens the textile''s original dimensionality—the subtle ridges and valleys created by centuries of uneven thread tension. Once you press a tapestry flat against a support, you lose information that no photograph or scan can recover." Lindström has developed an alternative method using a grid of individually adjustable micro-clamps that distribute weight without compressing the surface. Her technique requires roughly four times the labor hours of standard linen mounting.', $lyceon_json$[{"key":"A","text":"fundamentally unnecessary, since medieval tapestries are more resilient than conservators typically assume"},{"key":"B","text":"effective at preventing physical damage but problematic because they eliminate historically significant textural features"},{"key":"C","text":"outdated in every respect and in urgent need of replacement by modern digital imaging techniques"},{"key":"D","text":"too expensive for most museums to implement, which is why she developed a more affordable alternative"}]$lyceon_json$::jsonb, 'B', NULL, E'Lindström acknowledges that standard linen mounting prevents further tearing—demonstrating its effectiveness at preventing damage—but criticizes it for flattening the tapestry''s original dimensionality and causing irreversible loss of textural information. This supports the inference that she sees traditional methods as effective at preventing damage but problematic for eliminating historically significant features. The option calling preservation fundamentally unnecessary contradicts Lindström''s own work in conservation and her acknowledgment that weakened fibers need support. The option calling methods outdated in every respect overstates her position; she credits linen mounting with preventing tearing and does not advocate digital imaging as a replacement for physical conservation. The option about cost reverses the facts—her alternative requires four times the labor, making it more expensive, not more affordable.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NV5CGJ', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes the relationship between Mukherjee''s findings and Hahn''s proposal?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2P4IWYM', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'According to the passage, which detail best explains why the restoration of the Kiso River wetlands posed particular challenges for conservation planners?', E'In 2019, Japan''s Ministry of the Environment initiated a large-scale effort to restore wetland habitats along the Kiso River in Aichi Prefecture. The project aimed to reintroduce native plant species that had been displaced by decades of urban encroachment and agricultural runoff. However, planners quickly encountered a complication: the soil chemistry in the targeted zones had been so thoroughly altered by prolonged exposure to nitrogen-rich fertilizer runoff that many native wetland species could no longer germinate in it. Remediation of the soil required removing the top 40 centimeters of substrate across 17 hectares and replacing it with uncontaminated sediment sourced from upstream floodplains. This process alone consumed nearly 60 percent of the project''s initial three-year budget. Despite these obstacles, by 2023 the team had successfully reestablished populations of seven previously extirpated plant species.', $lyceon_json$[{"key":"A","text":"The native plant species selected for reintroduction had become extinct in the wild and could only be propagated from seed banks."},{"key":"B","text":"The soil in the restoration zones had been chemically altered by fertilizer runoff to the point that native species could not germinate in it."},{"key":"C","text":"Local government agencies refused to allocate sufficient funding to cover the costs of transporting replacement sediment."},{"key":"D","text":"Urban development along the Kiso River had physically eliminated the wetland areas, leaving no suitable terrain for restoration."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage explicitly states that prolonged exposure to nitrogen-rich fertilizer runoff altered soil chemistry so thoroughly that native species could no longer germinate. The option about chemically altered soil directly captures this stated challenge. The option about extinction and seed banks introduces information not found in the passage—it says species were displaced, not that they went extinct globally or required seed banks. The option about government funding refusal contradicts the passage, which notes that the soil remediation consumed most of the budget but does not mention any refusal to allocate funds. The option about physical elimination of wetland areas overstates what the passage says; it references urban encroachment as a cause of displacement, not total physical elimination of terrain.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PDWS5Y', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Victorian novelist George Meredith, whose 1879 work The Egoist satirized the self-absorption of the English upper classes _____ remained largely overlooked by twentieth-century literary critics until a 1971 reassessment by scholar Renata Voss renewed interest in his prose.', $lyceon_json$[{"key":"A","text":"classes"},{"key":"B","text":"classes;"},{"key":"C","text":"classes—"},{"key":"D","text":"classes,"}]$lyceon_json$::jsonb, 'D', NULL, E'The clause "whose 1879 work The Egoist satirized the self-absorption of the English upper classes" is a nonrestrictive relative clause modifying "George Meredith." It is introduced by a comma before "whose," so it must be closed with a matching comma after "classes" to properly delimit the parenthetical information before the main verb "remained." Omitting the comma after "classes" fails to close the nonrestrictive clause, fusing it into the main predicate. A semicolon after "classes" would incorrectly create a boundary between two independent clauses, but "remained largely overlooked" is the main verb of the sentence, not the start of a new clause. An em dash after "classes" creates mismatched punctuation because the clause was opened with a comma, not a dash; paired delimiters must match.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PE4CIN', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Based on the passage, what can most reasonably be inferred about the town''s residents?', E'When the municipal council of Ferncross, Vermont, announced in January 2024 that it would close the town''s only public library branch due to budget shortfalls, more than 400 residents attended the next council meeting—a gathering that exceeded the fire code capacity of the town hall. Within two weeks, a citizen-led fundraising campaign had collected $83,000 in private donations, surpassing the $71,000 annual operating cost the council had cited as unsustainable. The council subsequently reversed its decision, and the library reopened with extended Saturday hours funded entirely by the donated surplus.', $lyceon_json$[{"key":"A","text":"They regarded the public library as a valuable community resource worth preserving."},{"key":"B","text":"They believed the municipal council had deliberately misrepresented the library's operating costs."},{"key":"C","text":"They opposed all budget reductions proposed by the municipal council, not just the library closure."},{"key":"D","text":"They had previously organized similar fundraising campaigns for other public institutions in Ferncross."}]$lyceon_json$::jsonb, 'A', NULL, E'The massive turnout at the council meeting and the rapid fundraising effort that exceeded the library''s operating cost both indicate that residents considered the library a valuable resource worth preserving. The option about deliberate misrepresentation goes beyond what the passage supports—residents raised funds to cover the stated cost, which suggests they accepted the figure rather than disputed it. The option about opposing all budget reductions extends the residents'' actions far beyond what the passage describes; only the library closure prompted their response. The option about previous fundraising campaigns introduces information entirely absent from the passage, which describes no prior organizing efforts.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PF71B1', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Ceramicist Yara Okonkwo spent three years perfecting a glaze formula inspired by ninth-century Persian pottery _____ she ultimately created a finish that mimics the iridescent quality of Kashan tilework.', $lyceon_json$[{"key":"A","text":"pottery, she"},{"key":"B","text":"pottery she"},{"key":"C","text":"pottery. She"},{"key":"D","text":"pottery; she,"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence contains two independent clauses: "Ceramicist Yara Okonkwo spent three years perfecting a glaze formula inspired by ninth-century Persian pottery" and "she ultimately created a finish that mimics the iridescent quality of Kashan tilework." A period correctly separates these two independent clauses into distinct sentences. Using a comma alone between two independent clauses ("pottery, she") creates a comma splice. Omitting all punctuation ("pottery she") creates a fused sentence. Using a semicolon followed by a comma after the subject ("pottery; she,") incorrectly separates the subject "she" from its verb "ultimately created."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Q4CTA7', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing a research summary and wants to present a nuanced claim by acknowledging the limitations of a finding while still conveying its significance. Which choice most effectively uses information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QCAZRX', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the passage?', E'In 2019, marine biologist Anika Patel identified a previously unknown species of bioluminescent jellyfish in the deep trenches off the coast of Papua New Guinea. The organism, which Patel named Atolla pateli, produces a distinctive spiral pattern of blue-green light along its bell margin, unlike the concentric rings observed in related species. Her team documented seventeen individual specimens across three dive expeditions.', $lyceon_json$[{"key":"A","text":"To present a researcher's discovery of a new marine organism"},{"key":"B","text":"To argue that bioluminescent jellyfish are more diverse than previously believed"},{"key":"C","text":"To compare the light-producing mechanisms of different jellyfish species"},{"key":"D","text":"To evaluate the methodology used in deep-sea biological surveys"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage introduces Patel, names the new species she discovered, describes its distinguishing feature, and notes how many specimens were found. Its function is to present a researcher''s discovery of a new marine organism. The claim that bioluminescent jellyfish are more diverse than believed is an inference not made or implied by the passage. While the passage briefly mentions a difference in light patterns between the new species and related ones, its purpose is not to compare mechanisms — the comparison serves only to distinguish the new species. The passage does not discuss or assess research methodology at all.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TX4U3Z', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Which choice best describes how Asante''s analysis relates to Ferreira''s argument?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UDCY0N', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Entomologist Priya Venkatesh has documented over forty previously unknown beetle species in the cloud forests of northern Ecuador _____ her findings have prompted the regional government to designate three new protected habitats.', $lyceon_json$[{"key":"A","text":"Ecuador, consequently,"},{"key":"B","text":"Ecuador; consequently,"},{"key":"C","text":"Ecuador consequently,"},{"key":"D","text":"Ecuador. Consequently"}]$lyceon_json$::jsonb, 'B', NULL, E'Two independent clauses are joined here, and the conjunctive adverb "consequently" signals the logical relationship between them. A semicolon before a conjunctive adverb, followed by a comma after it ("Ecuador; consequently, her findings"), is the standard convention for joining independent clauses with a conjunctive adverb. Using a comma before "consequently" ("Ecuador, consequently,") creates a comma splice because a comma alone cannot join two independent clauses. Omitting punctuation before "consequently" ("Ecuador consequently,") produces a fused sentence. Using a period followed by "Consequently" without a comma ("Ecuador. Consequently her findings") omits the required comma after an introductory conjunctive adverb.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2USP365', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the passages, how would Solis most likely respond to Ferrin''s argument?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2W8ZM71', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the passage, "qualified" most nearly means', E'The Senator''s endorsement of the infrastructure proposal was far from unconditional. In her floor speech, she qualified her support by noting that the projected cost estimates relied on assumptions about steel prices that had not held true in any of the past seven fiscal quarters, and she urged the committee to revisit those projections before scheduling a vote.', $lyceon_json$[{"key":"A","text":"certified"},{"key":"B","text":"limited"},{"key":"C","text":"enhanced"},{"key":"D","text":"abandoned"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage states that the endorsement was "far from unconditional" and describes the Senator adding reservations about cost projections. "Limited" correctly captures the sense of restricting or placing conditions on her support. "Certified" means officially verified or endorsed without reservation, which directly contradicts the passage''s statement that her support was not unconditional. "Enhanced" means strengthened or improved, but the Senator is adding caveats that restrict her support, not strengthening it. "Abandoned" means to give up entirely, but the passage makes clear she still endorsed the proposal — she restricted her support rather than withdrawing it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XH58FX', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'The Okinawan practice of moai, in which small groups of friends commit to regular meetings and mutual financial support throughout their lives, has been credited as one factor in the island''s unusually high rate of centenarians. Researchers have noted that moai members report lower levels of chronic stress and stronger social bonds than those without such groups. _______ a 2019 longitudinal study from Naha found that participants in moai groups who relocated to mainland Japan experienced a measurable decline in self-reported well-being within three years of leaving their groups, suggesting the benefits depend on sustained participation rather than cultural heritage alone.', $lyceon_json$[{"key":"A","text":"Nevertheless,"},{"key":"B","text":"Moreover,"},{"key":"C","text":"Instead,"},{"key":"D","text":"In other words,"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence after the blank adds further evidence supporting the claim that moai participation benefits well-being, building on the prior sentence''s observation about lower stress and stronger bonds. "Moreover," correctly signals the addition of reinforcing evidence. "Nevertheless," incorrectly implies the new evidence contradicts what came before, when in fact it strengthens the same point. "Instead," suggests a replacement or alternative, but the study does not replace the previous finding; it supplements it. "In other words," indicates a restatement of the same idea in different terms, but the 2019 study introduces new information about relocation rather than rephrasing existing claims.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XUH5NK', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologists at the University of Bergen have long studied the migratory patterns of Atlantic cod in Norwegian fjords. Their latest survey, conducted over seventeen months, documented cod populations moving to deeper waters earlier in the season than previously recorded. _______ the researchers attributed this behavioral shift to rising sea surface temperatures, which have increased by 1.3 degrees Celsius in the region since 2004.', $lyceon_json$[{"key":"A","text":"Accordingly,"},{"key":"B","text":"In contrast,"},{"key":"C","text":"Granted,"},{"key":"D","text":"Specifically,"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence following the blank offers a causal explanation for the observed behavioral shift described in the preceding sentence. "Accordingly," correctly signals that the researchers'' attribution of the shift to rising temperatures follows logically from their observation. "In contrast," incorrectly implies a contradiction between the observation and the explanation, when in fact the explanation supports the observation. "Granted," introduces a concession, but no concession is being made here. "Specifically," suggests the next sentence narrows or elaborates on a general claim, but the sentence instead provides a cause, not a more specific restatement.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
